#include "MasteringPanel.h"
#include <algorithm>
namespace ssbb {
MasteringPanel::MasteringPanel(MasteringDSPChain&c):chain_(c){title_.setText("4. Mastering",juce::dontSendNotification);title_.setFont(juce::FontOptions(17.0f,juce::Font::bold));loudLabel_.setText("Loudness",juce::dontSendNotification);widthLabel_.setText("Width",juce::dontSendNotification);warmthLabel_.setText("Warmth",juce::dontSendNotification);for(auto*s:{&loud_,&width_,&warmth_}){s->setRange(0,1,.01);s->setSliderStyle(juce::Slider::LinearHorizontal);s->setTextBoxStyle(juce::Slider::TextBoxRight,false,44,22);}loud_.setValue(.65);width_.setValue(.2);warmth_.setValue(.2);addAndMakeVisible(title_);addAndMakeVisible(loudLabel_);addAndMakeVisible(widthLabel_);addAndMakeVisible(warmthLabel_);addAndMakeVisible(loud_);addAndMakeVisible(width_);addAndMakeVisible(warmth_);loud_.onValueChange=[this]{chain_.setLoudness(static_cast<float>(loud_.getValue()));};width_.onValueChange=[this]{chain_.setWidth(static_cast<float>(width_.getValue()));};warmth_.onValueChange=[this]{chain_.setWarmth(static_cast<float>(warmth_.getValue()));};}
void MasteringPanel::paint(juce::Graphics&g){g.setColour(juce::Colour(0xff1b2030));g.fillRoundedRectangle(getLocalBounds().toFloat(),8);}void MasteringPanel::resized(){auto r=getLocalBounds().reduced(10);title_.setBounds(r.removeFromLeft(140));for(auto p:{std::pair{&loudLabel_,&loud_},std::pair{&widthLabel_,&width_},std::pair{&warmthLabel_,&warmth_}}){p.first->setBounds(r.removeFromLeft(62));p.second->setBounds(r.removeFromLeft(std::max(100,r.getWidth()/3)));}}
} // namespace ssbb
